contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try different logging entrypoints and check they only succeed when approvedLoggers[msg.sender] is true.
    function run(address loggerToApprove, bytes32 digest, bytes32 r, bytes32 s, bytes32 txid, address keepAddress) public payable {
        // precondition: allow any addresses; nothing required
        // Initially, ensure approvedLoggers for this contract (msg.sender of calls to c) is read
        bool beforeApproved = c.approvedToLog(address(this));

        // Attempt a variety of log calls as this contract (msg.sender == address(this)).
        // Each call that requires approval should return false when not approved and true when approved.
        bool okCreatedBefore = c.logCreated(keepAddress);
        bool okGotSigBefore = c.logGotRedemptionSignature(digest, r, s);
        bool okRedeemedBefore = c.logRedeemed(txid);

        // Now, change approval for this contract via the owner's setter. The test contract deployed c, so it is the owner.
        // Set approvedLoggers[address(this)] to true.
        c.setApprovedLogger(address(this), true);

        bool afterApproved = c.approvedToLog(address(this));

        // After approval, the same logging calls should return true.
        bool okCreatedAfter = c.logCreated(keepAddress);
        bool okGotSigAfter = c.logGotRedemptionSignature(digest, r, s);
        bool okRedeemedAfter = c.logRedeemed(txid);

        // Also flip approval back to false and observe that subsequent calls return false again.
        c.setApprovedLogger(address(this), false);
        bool afterRevoked = c.approvedToLog(address(this));
        bool okCreatedRevoked = c.logCreated(keepAddress);

        // General rule: when approvedToLog is false, log* calls return false; when true, they return true.
        // Express using observed values before/after and without assuming initial beforeApproved value.
        assert(
            // beforeApproved matches the before-call returns (all should be equal to beforeApproved)
            (beforeApproved == okCreatedBefore) && (beforeApproved == okGotSigBefore) && (beforeApproved == okRedeemedBefore)
            // afterApproved matches the after-call returns
            && (afterApproved == okCreatedAfter) && (afterApproved == okGotSigAfter) && (afterApproved == okRedeemedAfter)
            // afterRevoked must be false and the revoked call must return false
            && (afterRevoked == false) && (okCreatedRevoked == false)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that setApprovedLogger changes only the single mapping entry for the target address
    // and leaves some other address's approval unchanged.
    function run(address target, address other, bool status) public payable {
        require(target != address(0) && other != address(0));
        // observe before-values
        bool beforeTarget = c.approvedToLog(target);
        bool beforeOther = c.approvedToLog(other);

        // call mutator as owner (this contract deployed c, so it is owner)
        c.setApprovedLogger(target, status);

        // observe after-values
        bool afterTarget = c.approvedToLog(target);
        bool afterOther = c.approvedToLog(other);

        // General rule: afterTarget equals the status we set; afterOther equals beforeOther (unchanged).
        assert(afterTarget == status && afterOther == beforeOther);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that calling any log... function does not change the approvedLoggers status
    // of msg.sender (this contract). The contract deployer is the owner so this contract
    // can set its own approved status via setApprovedLogger. We try both approved and
    // not-approved cases and ensure that after calling a log function the approval state
    // of this contract equals what it was before.
    function run(address keepAddr, address requester, bytes32 digest, uint256 utxoSize, bytes calldata redeemerOutputScript, uint256 requestedFee, bytes calldata outpoint, bytes32 r, bytes32 s, bytes32 x, bytes32 y, bool wasFraud, bytes32 txid) public payable {
        require(keepAddr != address(0) && requester != address(0));

        // observe approval status before
        bool before = c.approvedToLog(address(this));

        // Ensure both possible approval states are exercised: toggle to !before, then back
        c.setApprovedLogger(address(this), !before);
        bool mid = c.approvedToLog(address(this));

        // call a variety of log functions; each may return true or false depending on approval
        bool ok1 = c.logCreated(keepAddr);
        bool ok2 = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint);
        bool ok3 = c.logGotRedemptionSignature(digest, r, s);
        bool ok4 = c.logRegisteredPubkey(x, y);
        bool ok5 = c.logSetupFailed();
        bool ok6 = c.logFraudDuringSetup();
        bool ok7 = c.logFunded();
        bool ok8 = c.logCourtesyCalled();
        bool ok9 = c.logStartedLiquidation(wasFraud);
        bool ok10 = c.logRedeemed(txid);
        bool ok11 = c.logLiquidated();
        bool ok12 = c.logExitedCourtesyCall();

        // restore original approval state
        c.setApprovedLogger(address(this), before);
        bool after = c.approvedToLog(address(this));

        // General rule: calling any log* function (whether they returned true or false)
        // must NOT have permanently changed the approvedLoggers entry for msg.sender; after
        // restoring we are back to the original 'before' value. Also mid must equal !before
        // since we explicitly set it that way.
        assert(mid == !before && after == before);
    }

    receive() external payable { }
}

contract InvMutTest {
