    // Single public test function exercising setApprovedLogger and log* functions.
    // We assert that setting approval to a value makes approvedToLog reflect that value,
    // and that setting it back restores the original value.
    function run() public payable {
        // observe approval status before any change
        bool before = c.approvedToLog(address(this));

        // set to the opposite of before and observe
        c.setApprovedLogger(address(this), !before);
        bool flipped = c.approvedToLog(address(this));

        // call a few log functions to ensure they can be invoked in either state
        // results are observed but not required for the main invariant
        c.logFunded();
        c.logSetupFailed();
        c.logExitedCourtesyCall();

        // restore original approval state
        c.setApprovedLogger(address(this), before);
        bool restored = c.approvedToLog(address(this));

        // General rule: setApprovedLogger must have set the approval to the requested value (flipped == !before)
        // and restoring must return it to the original (restored == before).
        assert(flipped == (!before) && restored == before);
    }

    receive() external payable { }
}

