    // single public function with parameters selecting which log to call and its inputs
    function run(uint8 selector, address addrParam, bytes32 b1, bytes32 b2, uint256 n1, bytes calldata bs1, bytes calldata bs2) public payable {
        require(selector <= 11, "selector out of range");

        // read approval status before the call
