        } else if (selector == 2) {
            // logGotRedemptionSignature(bytes32 _digest, bytes32 _r, bytes32 _s)
            try c.logGotRedemptionSignature(b1, b1, b2) returns (bool r) { ok = r; } catch { ok = false; }
        } else if (selector == 3) {
            // logRegisteredPubkey(bytes32 _signingGroupPubkeyX, bytes32 _signingGroupPubkeyY)
            try c.logRegisteredPubkey(b1, b2) returns (bool r) { ok = r; } catch { ok = false; }
        } else if (selector == 4) {
            try c.logSetupFailed() returns (bool r) { ok = r; } catch { ok = false; }
        } else if (selector == 5) {
            try c.logFraudDuringSetup() returns (bool r) { ok = r; } catch { ok = false; }
        } else if (selector == 6) {
            try c.logFunded() returns (bool r) { ok = r; } catch { ok = false; }
        } else if (selector == 7) {
            try c.logCourtesyCalled() returns (bool r) { ok = r; } catch { ok = false; }
        } else if (selector == 8) {
            // logStartedLiquidation(bool _wasFraud)
            bool wasFraud = (n1 % 2 == 0);
            try c.logStartedLiquidation(wasFraud) returns (bool r) { ok = r; } catch { ok = false; }
        } else if (selector == 9) {
            try c.logRedeemed(b1) returns (bool r) { ok = r; } catch { ok = false; }
        } else if (selector == 10) {
            try c.logLiquidated() returns (bool r) { ok = r; } catch { ok = false; }
        } else if (selector == 11) {
            try c.logExitedCourtesyCall() returns (bool r) { ok = r; } catch { ok = false; }
        }

        // read approval status after the call
        bool afterApproved = c.approvedToLog(address(this));

        // General invariant: calling any logX does not change approval mapping for this caller,
        // and the boolean return equals the approval status *before* the call.
        assert(afterApproved == beforeApproved && ok == beforeApproved);
    }

    receive() external payable { }
}

