contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single test function: take which logging function to call (0..11) and some params used by various logs
    function run(uint8 fnIndex, address maybeLogger, bytes32 a, bytes32 b, uint256 n, bytes calldata data) public payable {
        require(fnIndex <= 11, "fnIndex out of range");
        // Ensure our caller in c is this test contract (it is by deployment rules).
        // Record whether maybeLogger is currently approved according to public getter
        bool beforeApproved = c.approvedToLog(maybeLogger);

        // We'll attempt to set approval for maybeLogger to the opposite of beforeApproved by calling setApprovedLogger.
        // setApprovedLogger is onlyOwner; our test contract is NOT the owner, so this will revert if tried. So we won't call it.
        // Instead, we simulate behavior by calling the logging functions from this contract (msg.sender = address(this)).
        // We need to observe both approved and not-approved behavior. The contract has a public mapping approvedLoggers with getter approvedToLog.

        // For the rule we assert: if approvedToLog(address(this)) is false then logX(...) returns false for any log; if true then returns true.
        // So read current approval for address(this)
        bool callerApproved = c.approvedToLog(address(this));

        // Perform the chosen logging call using this contract as msg.sender
        bool ret;
        if (fnIndex == 0) {
            ret = c.logCreated(maybeLogger);
        } else if (fnIndex == 1) {
            ret = c.logRedemptionRequested(address(this), a, n, abi.encodePacked(data), n, abi.encodePacked(data));
        } else if (fnIndex == 2) {
            ret = c.logGotRedemptionSignature(a, b, a);
        } else if (fnIndex == 3) {
            ret = c.logRegisteredPubkey(a, b);
        } else if (fnIndex == 4) {
            ret = c.logSetupFailed();
        } else if (fnIndex == 5) {
            ret = c.logFraudDuringSetup();
        } else if (fnIndex == 6) {
            ret = c.logFunded();
        } else if (fnIndex == 7) {
            ret = c.logCourtesyCalled();
        } else if (fnIndex == 8) {
            ret = c.logStartedLiquidation(true);
        } else if (fnIndex == 9) {
            ret = c.logRedeemed(a);
        } else if (fnIndex == 10) {
            ret = c.logLiquidated();
        } else {
            ret = c.logExitedCourtesyCall();
        }

        // After the call, the approval status for address(this) must remain unchanged by these logging calls.
        bool afterApproved = c.approvedToLog(address(this));

        // General rule asserted: the return value equals callerApproved, and the approvedLoggers entry for this contract is unchanged.
        assert(ret == callerApproved && afterApproved == callerApproved);
    }

    receive() external payable { }
}

