    // single public test function: take a bool to decide whether to set approval, and an address _keep
    function run(bool wantApprove, address _keep) public payable {
        // record approval status before any actions
        bool beforeApproved = c.approvedToLog(address(this));

        // If caller wants to become approved, try to set it via owner-only setter.
        // The deploying setup of the checker gives this contract as the deployer of c, so
        // onlyOwner should allow this contract to call setApprovedLogger. But that may revert
        // if this contract isn't owner; guard with try/catch.
        if (wantApprove) {
            // perform as a top-level state-changing call, capture revert via try/catch
            try c.setApprovedLogger(address(this), true) {
                // no-op on success
            } catch {
                // ignore revert; approval may remain unchanged
            }
        }

        // read approval after attempted change
        bool afterApproved = c.approvedToLog(address(this));

        // Now call a mutating log function and capture whether it reverted and its boolean return.
        bool returned;
        bool didRevert;
        try c.logCreated(_keep) returns (bool r) {
            returned = r;
            didRevert = false;
        } catch {
            // if it reverted treat returned as false for the assertion (revert implies no true return)
            returned = false;
            didRevert = true;
        }

        // General rule asserted: the logCreated function must not revert; it must simply return whether caller is approved.
        // We express: it never reverts AND its returned value equals the approval status at call time (after any setApprovedLogger).
